solution:
%dw 2.0
output application/json
---
payload map (job) -> {
  id: job.id,
  status: job.retries match {
    case n if (n is Number and n >= 3) -> "ESCALATE"
    case n is Number -> "RETRYING"
    case null -> "NEW"
    else -> "INVALID"
  }
}

